import { execFileSync, execSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { createServer } from "node:net";
import { join } from "node:path";
import { isDatabaseCapabilityEnabled } from "../capabilities.js";
import { toComposeProjectName } from "../compose-project-name.js";
import { AUTOGENERATED_DIR, PACKAGE_JSON, PROJECT_JSON } from "../constants.js";
import { formatCount } from "../formatting.js";
import { runCachedHostCommand, SHARED_DOCKER_PS, } from "../host-command-cache.js";
import { toNamePortsLines } from "../host-port-config.js";
import { findProjectRoot } from "../paths.js";
import { findPortOwner, getPortSetting, mappingPublishesHostPort, } from "../port-owner.js";
import { isApiServiceType } from "../resource-kind.js";
import { redactProjectText } from "../secret-redaction.js";
import { healthCheckPathOf, isHealthCheckDisabled } from "../service-manifest.js";
